
#' Test PRS Association with a Target Neale Lab UK Biobank GWAS
#'
#' Tests whether a polygenic risk score (PRS), represented by a SNP weight
#' file generated by [build_prs_weights()], is associated with the phenotype
#' of a target Neale Lab UK Biobank GWAS summary statistics dataset using the
#' summary-statistics PRS association method implemented in this package.
#'
#' The function reads a PRS SNP weight file and a target GWAS summary
#' statistics file, aligns SNPs between the two datasets, and estimates the
#' effect of the PRS on the target phenotype directly from GWAS summary
#' statistics without requiring individual-level genotype or phenotype data.
#'
#' @param w_snpfile Character string. Path to the PRS SNP weight file
#'   generated by [build_prs_weights()]. The file should contain the selected
#'   SNPs and their corresponding effect-size weights.
#'
#' @param t_bgzfile Character string. Path to the compressed target Neale Lab
#'   UK Biobank GWAS summary statistics file in bgzip format (e.g.,
#'   `.bgz` or `.bgz.gz`). The file should contain GWAS summary statistics
#'   for the target phenotype.
#' 
#' 
#' @param weight Character string specifying how to calculate the PRS SNP
#'   weights. Must be one of:
#'   \describe{
#'     \item{`"beta"`}{Use the source GWAS effect estimate:
#'       `beta`.}
#'     \item{`"z"`}{Use the source GWAS Z statistic:
#'       `beta / se`. This is the default.}
#'     \item{`"max"`}{Use `beta / (se^2 * 2 * minor_AF * (1 - minor_AF))`,
#'       where `minor_AF` is the source GWAS minor allele frequency.}
#'   }
#'   Defaults to `"beta"`. 
#' 
#' @return
#' A named vector containing:
#' \describe{
#'   \item{nsnps}{Number of SNPs included in the PRS analysis.}
#'   \item{effect_est}{Estimated effect of the PRS on the target phenotype.}
#'   \item{effect_se}{Standard error of the estimated PRS effect.}
#'   \item{Z_a}{Z statistic for testing the null hypothesis that the PRS
#'   effect is zero.}
#'   \item{p_value}{Two-sided p-value for the PRS association test.}
#' }
#'
#' @details
#' The function estimates the association between a PRS and a target phenotype
#' directly from GWAS summary statistics. It matches variants between the
#' PRS weight file and the target GWAS, aligns effect alleles, and then
#' estimates the PRS effect using the selected `weight` option.
#'
#' 
#'
#' The function performs the following steps:
#' \enumerate{
#'   \item Reads the PRS SNP weight file generated by
#'         [build_prs_weights()].
#'   \item Reads the target Neale Lab UK Biobank GWAS summary statistics.
#'   \item Matches SNPs between the PRS weight file and the target GWAS
#'         summary statistics.
#'   \item Aligns effect alleles between the two datasets.
#'   \item Applies the package's summary-statistics PRS method to estimate
#'         the effect of the PRS on the target phenotype.
#'   \item Returns the number of SNPs included in the analysis, the estimated
#'         PRS effect, its standard error, Z statistic, and corresponding
#'         p-value.
#' }
#'
#' @examples
#' \dontrun{
#' prs_result <- test_prs_association(
#'   w_snpfile = "prs_weights.txt",
#'   t_bgzfile = "target_gwas.txt.bgz",
#'   weight = "beta"
#' )
#'
#' prs_result
#' }
#'
#' @seealso
#' [build_prs_weights()]
#'
#' @export
test_prs_association<-function(w_snpfile, t_bgzfile, weight = c("beta", "z", "max")) {
	#library(data.table)
	
	weight <- match.arg(weight)
	
# -------------------------------------------------------------------------
# get PRS weights from wsnpfile
# -------------------------------------------------------------------------
	cat("Loading independent lead variants...\n")
	w_prs <- data.table::fread(w_snpfile)
	
	required_w_cols <- c("variant", "ref", "alt", "beta", "se", "minor_AF")
	missing_w_cols <- setdiff(required_w_cols, names(w_prs))
	
	if (length(missing_w_cols) > 0) {
		stop(
				"The PRS weight file is missing required columns: ",
				paste(missing_w_cols, collapse = ", ")
		)
	}
	
	
	# Expects: variant, ref, alt, beta, se, minor_AF
	data.table::setnames(w_prs, 
			old = c("beta", "se", "minor_AF"), 
			new = c("beta_w", "se_w", "af_w"))
	
	

	# Validate source-GWAS values used by beta and z weights.
	if (any(!is.finite(w_prs$beta_w))) {
		stop("The PRS weight file contains non-finite beta values.")
	}
	if (any(!is.finite(w_prs$se_w)) ||
			any(w_prs$se_w <= 0)) {
		stop("All source-GWAS standard errors must be finite and greater than zero.")
	}
	
# -------------------------------------------------------------------------
# Construct requested SNP weights
# -------------------------------------------------------------------------
	if (weight == "beta") {
		w_prs[, w_i := beta_w]
	} else if (weight == "z") {
		w_prs[, w_i := beta_w / se_w]
	} else if (weight == "max") {
		w_prs[, w_i :=
						beta_w / (se_w^2 * 2 * af_w * (1 - af_w))]
	}
	if (any(!is.finite(w_prs$w_i))) {
		stop(
				"The selected weighting scheme produced non-finite SNP weights."
		)
	}	
	
	
# -------------------------------------------------------------------------
# Load target  Summary Statistics
# -------------------------------------------------------------------------
	cat("Loading target outcome GWAS ...\n")
	
# Read target GWAS
	outcome_gwas <- data.table::fread(
			t_bgzfile,
			select = c("variant", "beta", "se", "minor_AF"),
			colClasses = c(variant = "character", beta = "numeric", se = "numeric", minor_AF = "numeric")
	)
	
	required_t_cols <- c("variant", "beta", "se", "minor_AF")
	missing_t_cols <- setdiff(required_t_cols, names(outcome_gwas))
	if (length(missing_t_cols) > 0) {
		stop(
				"The target GWAS file is missing required columns: ",
				paste(missing_t_cols, collapse = ", ")
		)
	}
		
	
	
# Filter the target dataset to candidate SNPs.
	outcome_sub <- outcome_gwas[variant %in% w_prs$variant]	
	
	if (nrow(outcome_sub) == 0L) {
		stop("No variants from the PRS weight file were found in the target GWAS.")
	}
	
	
	cat("Parsing variant coordinates (chr:pos:ref:alt) for outcome dataset...\n")
	
	# DYNAMICALLY SPLIT 'variant' (e.g. 1:15791:C:T) into dedicated columns
	outcome_sub[, c("chr_out", "pos_out", "ref_out", "alt_out") := data.table::tstrsplit(variant, ":", fixed = TRUE)]
	
	# Rename remaining numeric columns
	data.table::setnames(outcome_sub, 
			old = c("beta", "se", "minor_AF"), 
			new = c("beta_out", "se_out", "af_out"))
	
# -------------------------------------------------------------------------
# Merge and Perform Strand/Allele Alignment
# -------------------------------------------------------------------------
	cat("Merging datasets and checking allele alignment...\n")
	merged_df <- merge(w_prs, outcome_sub, by = "variant")
	
# Check for swapped alleles (e.g., source gwas  has C/T, target gwas has T/C)
	merged_df[, allele_flip := (ref == alt_out & alt == ref_out)]
	merged_df[, allele_match := (ref == ref_out & alt == alt_out)]
	
# Filter out unaligned or multi-allelic mismatches, Keep only valid aligned variants
	merged_df <- merged_df[allele_match == TRUE | allele_flip == TRUE]
	
	if (nrow(merged_df) == 0L) {
		stop("No variants remained after allele alignment.")
	}
	
# Align outcome beta: if alleles are flipped, reverse the sign of beta_out
	merged_df[, b_hat := ifelse(allele_flip == TRUE, -beta_out, beta_out)]
	merged_df[, var_b_hat := se_out^2]
	
	
	
# -------------------------------------------------------------------------
# Calculate target genotype Var(X_i)
# -------------------------------------------------------------------------
	invalid_af <- !is.finite(merged_df$af_out) |
			merged_df$af_out <= 0 |
			merged_df$af_out >= 1
	if (any(invalid_af)) {
		stop(
				"Target minor_AF must be finite and strictly between zero and one."
		)
	}
	if (any(!is.finite(merged_df$se_out)) ||
			any(merged_df$se_out <= 0)) {
		stop(
				"All target GWAS standard errors must be finite and greater than zero."
		)
	}

# Using Hardy-Weinberg Equilibrium: Var(X_i) = 2 * p * (1 - p)
	merged_df[, var_X := 2 * af_out * (1 - af_out)]
	
	
	
# -------------------------------------------------------------------------
# Estimate PRS effect
# -------------------------------------------------------------------------
	cat("Calculating Z_a score...\n")
	
#PRS effect estimator
	effect_numerator <- sum(merged_df$w_i * merged_df$var_X * merged_df$b_hat, na.rm = TRUE)
	effect_denominator <-sum((merged_df$w_i^2) * (merged_df$var_X))
	effect_est<-effect_numerator/effect_denominator
	
#PRS effect estimator variance
	effectVar_numerator<-sum((merged_df$w_i^2) * (merged_df$var_X^2) * merged_df$var_b_hat, na.rm = TRUE)
	effectVar_denominator<-effect_denominator^2
	effectVar<-effectVar_numerator/effectVar_denominator
	effect_se<-sqrt(effectVar)
	
# PRS statistic Z Numerator: Sum_i [ w_i * Var(X_i) * b_hat_i ]
	# z_numerator <- sum(merged_df$w_i * merged_df$var_X * merged_df$b_hat, na.rm = TRUE)
	
# PRS statistic Z Denominator: sqrt( Sum_i [ w_i^2 * Var(X_i)^2 * Var(b_hat_i) ] )
	# z_denominator <- sqrt(sum((merged_df$w_i^2) * (merged_df$var_X^2) * merged_df$var_b_hat, na.rm = TRUE))
	
# Calculate PRS statistic Z_a
	# Z_a <- z_numerator / z_denominator
	Z_a <- effect_est / effect_se
	
# Compute two-tailed p-value from standard normal distribution
	p_value <- 2 * pnorm(-abs(Z_a))
	
# -------------------------------------------------------------------------
# Display Results
# -------------------------------------------------------------------------
	cat("\n===========================================\n")
	cat("          PRS ASSOCIATION RESULTS          \n")
	cat("===========================================\n")
	cat(sprintf("Number of SNPs analyzed : %d\n", nrow(merged_df)))
	cat(sprintf("PRS effect estimate           : %.4f\n", effect_est))
	cat(sprintf("PRS effect SE           : %.4f\n", effect_se))
	cat(sprintf("PRS Z_a Statistic           : %.4f\n", Z_a))
	cat(sprintf("PRS P-value                 : %e\n", p_value))
	cat("===========================================\n")
	
	if (p_value < 0.05) {
		cat("Result: Significant association detected.\n")
	} else {
		cat("Result: No statistically significant association detected.\n")
	}
	
	# Return named numeric vector of length 5
	res <- c(
			nsnps      = as.numeric(nrow(merged_df)),
			effect_est = as.numeric(effect_est),
			effect_se  = as.numeric(effect_se),
			Z_a        = as.numeric(Z_a),
			p_value    = as.numeric(p_value)
	)
	
	return(res)
}





